import React, { useState, useEffect } from "react";

function Home() {
  const [resumeText, setResumeText] = useState("");
  const [jobDesc, setJobDesc] = useState("");
  const [result, setResult] = useState(null);
  const [matchData, setMatchData] = useState(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) window.location.href = "/login";
  }, []);

  // =========================
  // OPTIMIZE
  // =========================
  const handleOptimize = async () => {
    if (!resumeText || !jobDesc) {
      alert("Provide resume + job description");
      return;
    }

    setLoading(true);

    try {
      const res = await fetch("http://localhost:5000/api/resume/optimize", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: JSON.stringify({ resumeText, jobDesc }),
      });

      const data = await res.json();
      setResult(data);
    } catch {
      alert("Error");
    }

    setLoading(false);
  };

  // =========================
  // MATCH
  // =========================
  const handleMatch = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/resume/match", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: "Bearer " + localStorage.getItem("token"),
        },
        body: JSON.stringify({ resumeText, jobDesc }),
      });

      const data = await res.json();

      console.log("MATCH DATA:", data); // debug

      setMatchData(data);
    } catch {
      alert("Match failed");
    }
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>CareerForge Pro 🚀</h1>

      <div style={styles.card}>
        <textarea
          placeholder="Paste Resume"
          value={resumeText}
          onChange={(e) => setResumeText(e.target.value)}
          style={styles.textarea}
        />

        <textarea
          placeholder="Paste Job Description"
          value={jobDesc}
          onChange={(e) => setJobDesc(e.target.value)}
          style={styles.textarea}
        />

        <button style={styles.button} onClick={handleOptimize}>
          {loading ? "Optimizing..." : "Optimize Resume"}
        </button>

        <button style={styles.button2} onClick={handleMatch}>
          Check Job Match
        </button>
      </div>

      {/* ================= RESULT ================= */}
      {result && (
        <div style={styles.resultCard}>
          <h2>ATS Score: {result.score}</h2>

          <pre style={styles.cleanText}>
            {result.optimizedText}
          </pre>
        </div>
      )}

      {/* ================= MATCH ================= */}
      {matchData && (
        <div style={styles.resultCard}>
          <h2>Match Score: {matchData.matchScore}%</h2>

          <h3>Matched Skills</h3>
          <p>{matchData.matchedSkills.join(", ")}</p>

          <h3>Missing Skills</h3>
          <p>{matchData.missingSkills.join(", ")}</p>

          <h3>Job Opportunities</h3>

          {matchData.recommendations.map((job, i) => (
            <div key={i} style={styles.jobCard}>
              <strong>{job.company}</strong>
              <p>Chance: {job.chance}%</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ===================== STYLES =====================
const styles = {
  container: {
    background: "#561C24",
    minHeight: "100vh",
    padding: "20px",
    color: "#E8D8C4",
  },

  heading: {
    textAlign: "center",
    marginBottom: "20px",
  },

  card: {
    background: "#6D2932",
    padding: "20px",
    borderRadius: "10px",
    maxWidth: "600px",
    margin: "auto",
  },

  textarea: {
    width: "100%",
    height: "120px",
    marginBottom: "10px",
    padding: "10px",
    borderRadius: "6px",
    border: "none",
    background: "#C7B7A3",
    color: "#000",
  },

  button: {
    width: "100%",
    padding: "10px",
    marginTop: "10px",
    background: "#E8D8C4",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
  },

  button2: {
    width: "100%",
    padding: "10px",
    marginTop: "10px",
    background: "#C7B7A3",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
  },

  resultCard: {
    background: "#6D2932",
    padding: "20px",
    marginTop: "20px",
    borderRadius: "10px",
    maxWidth: "700px",
    marginLeft: "auto",
    marginRight: "auto",
  },

  cleanText: {
    whiteSpace: "pre-wrap",
    background: "#561C24",
    padding: "10px",
    borderRadius: "6px",
    fontSize: "14px",
  },

  jobCard: {
    background: "#561C24",
    padding: "10px",
    marginTop: "10px",
    borderRadius: "6px",
  },
};

export default Home;
